        "parser": "file",
        "find": {
            "set sv_hostname ": "set sv_hostname \"{{server.environment.SERVER_NAME}}\"",
            "set sv_maxclients ": "set sv_maxclients {{server.environment.MAX_PLAYERS}}",
            "set server.private ": "set server.private {{server.environment.SERVER_PRIVATE}}",
            "set g_password ": "set g_password \"{{server.environment.SERVER_PASSWORD}}\"",
            "set rcon.server.password ": "set rcon.server.password \"{{server.environment.RCON_PASSWORD}}\"",
            "set g_motd ": "set g_motd \"{{server.environment.MOTD}}\"",
            "set g_bot_defaultFill ": "set g_bot_defaultFill {{server.environment.BOT_FILL}}",
            "map ": "map {{server.environment.MAP}}"
        }
    }
}
